// Creative roster proposals only. No runtime or voice-manifest writes.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
const dir=path.dirname(fileURLToPath(import.meta.url));
const game=path.resolve(dir,'../../..');
const catalogue=JSON.parse(fs.readFileSync(path.join(dir,'card-catalogue.json')));
const rows=[];
const accents={reason:'#3D7BFF',emotion:'#E8384F',perception:'#2FBF71',language:'#F2B632',imagination:'#A05CF0',memory:'#C9C9D6'};
function sharedSfx(card){
 const cues=['card-play','hit','defeat'];
 if(/heal|health/i.test(card.text))cues.push('heal');
 if(/Guard|Shield|prevent/i.test(card.text))cues.push('block');
 if(/draw|look|reveal/i.test(card.text))cues.push('reveal');
 if(/Fate|event|occurrence/i.test(card.text))cues.push('fate-warp');
 if(/Axiom/i.test(card.text))cues.push('axiom');
 return cues;
}
function add(colour, data){
 for(const row of data.trim().split('\n')){
  const [concept,pun,person,silhouette,prop,joke,mechanicLink,source,familiarity,voice]=row.split('|').map(s=>s.trim());
  const card=catalogue.cards.find(c=>c.name===concept&&c.kind==='creature'&&c.affinity===colour);
  assert(card,'Unknown concept '+concept);
  rows.push({mechanicalId:card.id,workingName:card.name,proposedName:pun,inspiration:person,colour,rarity:card.rarity,acquisition:card.acquisition,
   silhouette,signatureProp:prop,jokeAngle:joke,mechanicLink,source,familiarity:'Teacher-review assumption: '+familiarity,
   voiceDirection:voice,sharedSfx:sharedSfx(card),artId:card.art,palette:{accent:accents[colour],shadow:'ink-brown and midnight violet; restrained affinity rim light',materials:'worn cloth/leather or painted metal; no pristine plastic'},
   promptReferences:['design/source-assets/0-style/style-board.png','assets/creatures/astrophysicat-idle.webp'],
   overlap:'New persona, not an alternate print of an existing collectible. Keep original mechanical ID; same animal silhouette never merges species identity.',
   status:'Persona/visual proposal, not approved, generated, voiced, implemented or balance-tested',
   mechanicalContract:{cost:card.cost,attack:card.attack,health:card.health,text:card.text,gates:card.gates}});
 }
}
